pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0) && actor != address(this));
        NonSupporter adversary = new NonSupporter();
        vm.prank(address(adversary));
        vm.deal(address(adversary), 0);
        try c.airDrop() {
            assertEq(c.tokenBalance(address(adversary)), 0);
        } catch {
            assertTrue(true);
        }
    }
}

contract NonSupporter {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Wrong Token"));
    }
}
